/** Shared Inspector/Atlas presentation; no new panel or theme. */
export function renderSpatialEvidence(host:HTMLElement,steps:EvidenceStep[],sources?:Record<string,string>){
 const group=document.createElement('details');group.className='spatial-evidence';group.open=false;const title=document.createElement('summary');title.textContent=t('field.evidence');group.append(title);host.append(group);
 const list=document.createElement('ol');group.append(list);for(const step of steps){const row=document.createElement('li');row.dataset.relation=step.relation;row.textContent=`${t('evidence.'+step.relation)} · ${step.sourceType}: ${step.sourceIdentity} · ${t('atlas.'+step.precision)}`;list.append(row);if(step.reason){const p=document.createElement('p');p.textContent=t('field.'+step.reason);row.append(p);}}
 if(sources){const detail=document.createElement('details'),label=document.createElement('summary');label.textContent=t('atlas.sources')+' · SHA-256';detail.append(label);group.append(detail);const hashes=document.createElement('ul');detail.append(hashes);for(const [name,hash] of Object.entries(sources)){const row=document.createElement('li');row.textContent=name+' · '+hash;hashes.append(row);}}
}

/** CSS-pixel view of a raw local plane. Never converts units or invents geography. */
export class FieldPlanView {
 width=1;height=1;fit=1;scale=1;centerX=0;centerY=0;
 constructor(public bounds:readonly [number,number,number,number]){this.reset();}
 fitTo(bounds:readonly [number,number,number,number]){this.bounds=bounds;this.resize(this.width,this.height);this.reset();}
 resize(width:number,height:number){const ratio=this.scale/this.fit;this.width=Math.max(1,width);this.height=Math.max(1,height);this.fit=Math.min(Math.max(1,this.width-48)/Math.max(1,this.bounds[1]-this.bounds[0]),Math.max(1,this.height-48)/Math.max(1,this.bounds[3]-this.bounds[2]));this.scale=this.fit*ratio;}
 reset(){this.centerX=(this.bounds[0]+this.bounds[1])/2;this.centerY=(this.bounds[2]+this.bounds[3])/2;this.scale=this.fit;}
 point(x:number,y:number):[number,number]{return [this.width/2+(x-this.centerX)*this.scale,this.height/2-(y-this.centerY)*this.scale];}
 raw(x:number,y:number):[number,number]{return [this.centerX+(x-this.width/2)/this.scale,this.centerY-(y-this.height/2)/this.scale];}
 pan(dx:number,dy:number){this.centerX-=dx/this.scale;this.centerY+=dy/this.scale;}
 zoom(factor:number,x=this.width/2,y=this.height/2){const anchor=this.raw(x,y);this.scale=Math.max(this.fit*.1,Math.min(this.fit*30,this.scale*factor));this.centerX=anchor[0]-(x-this.width/2)/this.scale;this.centerY=anchor[1]+(y-this.height/2)/this.scale;}
}
/** Shared pointer coordinates/capture for existing SVG and Canvas, including pinch. */
function planInput(surface:HTMLElement|SVGSVGElement,view:FieldPlanView,owner:ResourceScope,draw:()=>void,pick?:(x:number,y:number)=>void){
 const pointers=new Map<number,[number,number]>();let moved=false,origin:[number,number]=[0,0],pair:{x:number;y:number;distance:number}|null=null;
 let touchTap:{time:number;x:number;y:number}|null=null;
 // Inspector opens during pointerup. Suppress that tap's compatibility click,
 // which could otherwise hit a newly exposed Inspector button underneath it.
 owner.listen(document,'click',((e:PointerEvent)=>{if(e.pointerType!=='touch')return;const tap=touchTap;if(!tap)return;touchTap=null;if(e.timeStamp-tap.time>=0&&e.timeStamp-tap.time<500&&Math.hypot(e.clientX-tap.x,e.clientY-tap.y)<2){e.preventDefault();e.stopImmediatePropagation();}}) as EventListener,{capture:true});
 const local=(e:PointerEvent|WheelEvent)=>{const r=surface.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top] as [number,number];};
 const measure=()=>{const p=[...pointers.values()];return p.length===2?{x:(p[0][0]+p[1][0])/2,y:(p[0][1]+p[1][1])/2,distance:Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1])}:null;};
 const release=(id:number)=>{if(surface.hasPointerCapture(id))surface.releasePointerCapture(id);};
 owner.own(()=>{for(const id of pointers.keys())release(id);pointers.clear();});
 owner.listen(surface,'pointerdown',((e:PointerEvent)=>{if(e.button!==0||pointers.size>=2||(e.target as Element).closest('.field-node,.field-edge'))return;e.preventDefault();surface.focus({preventScroll:true});if(!pointers.size){moved=false;origin=local(e);}pointers.set(e.pointerId,local(e));surface.setPointerCapture(e.pointerId);pair=measure();if(pair)moved=true;}) as EventListener);
 owner.listen(surface,'pointermove',((e:PointerEvent)=>{const before=pointers.get(e.pointerId);if(!before)return;const at=local(e);pointers.set(e.pointerId,at);const next=measure();if(next&&pair){view.zoom(next.distance/Math.max(1,pair.distance),pair.x,pair.y);view.pan(next.x-pair.x,next.y-pair.y);draw();}else{const dx=at[0]-before[0],dy=at[1]-before[1];if(Math.hypot(at[0]-origin[0],at[1]-origin[1])>2)moved=true;if(moved){view.pan(dx,dy);draw();}}pair=next;}) as EventListener);
 const up=(e:PointerEvent)=>{if(!pointers.has(e.pointerId))return;const at=local(e),tap=!moved&&pointers.size===1&&e.type==='pointerup';pointers.delete(e.pointerId);if(e.type!=='pointerup')release(e.pointerId);e.preventDefault();pair=measure();if(tap){if(pick&&e.pointerType==='touch')touchTap={time:e.timeStamp,x:e.clientX,y:e.clientY};pick?.(...at);}};
 owner.listen(surface,'pointerup',up as EventListener);owner.listen(surface,'pointercancel',up as EventListener);
 owner.listen(surface,'lostpointercapture',((e:PointerEvent)=>{pointers.delete(e.pointerId);pair=measure();}) as EventListener);
 owner.listen(surface,'wheel',((e:WheelEvent)=>{e.preventDefault();view.zoom(e.deltaY<0?1.1:1/1.1,...local(e));draw();}) as EventListener,{passive:false});
}

